ALTER TABLE public.visits ADD COLUMN IF NOT EXISTS pro_loop_enabled boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.visits.pro_loop_enabled IS 'New closed-loop work/GPS enforcement is enabled per visit only after portal rollout; legacy booked visits keep existing completion rules.';
CREATE OR REPLACE FUNCTION public.pro_required_checklist_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p uuid; c jsonb; legacy jsonb; k text; BEGIN IF NOT NEW.pro_loop_enabled THEN RETURN NEW; END IF; IF NEW.status::text='complete' AND OLD.status::text<>'complete' AND NOT coalesce(NEW.is_sample,false) THEN FOR p IN SELECT NEW.assigned_pro_id UNION SELECT coalesce(NEW.backup_pro_id,t.partner_pro_id) FROM public.cleaning_teams t WHERE t.id=NEW.cleaning_team_id AND t.kind='paired_pros' AND NEW.size_tier=5 LOOP IF p IS NULL THEN RAISE EXCEPTION 'pro_assignment_required'; END IF; c:=NULL;legacy:=NULL; SELECT checks INTO c FROM public.pro_visit_checks WHERE visit_id=NEW.id AND pro_id=p; IF NEW.service::text='cleaning' THEN SELECT checks INTO legacy FROM public.cleaning_visit_checks WHERE visit_id=NEW.id AND pro_id=p; END IF; c:=coalesce(legacy,'{}'::jsonb)||coalesce(c,'{}'::jsonb); FOREACH k IN ARRAY public.pro_required_check_keys(NEW.service::text,NEW.visit_kind) LOOP IF NOT coalesce((c->>k)::boolean,false) THEN RAISE EXCEPTION 'service_checklist_required:%',k; END IF; END LOOP; END LOOP; IF EXISTS(SELECT 1 FROM public.addon_attaches a WHERE a.visit_id=NEW.id AND a.status='pending_visit') THEN RAISE EXCEPTION 'booked_addons_incomplete'; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.pro_gps_visit_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT NEW.pro_loop_enabled THEN RETURN NEW; END IF; IF NEW.check_in_at IS DISTINCT FROM OLD.check_in_at AND NEW.check_in_at IS NOT NULL THEN IF NEW.address_lat IS NULL OR NEW.address_lng IS NULL OR public.pro_gps_distance(NEW.check_in_lat,NEW.check_in_lng,NEW.address_lat,NEW.address_lng)>150 THEN IF length(trim(coalesce(NEW.check_in_location_reason,'')))<10 THEN RAISE EXCEPTION 'outside_150m_or_unverified_reason_required'; END IF; END IF; END IF; IF NEW.check_out_at IS DISTINCT FROM OLD.check_out_at AND NEW.check_out_at IS NOT NULL THEN IF NEW.address_lat IS NULL OR NEW.address_lng IS NULL OR public.pro_gps_distance(NEW.check_out_lat,NEW.check_out_lng,NEW.address_lat,NEW.address_lng)>150 THEN IF length(trim(coalesce(NEW.check_out_location_reason,'')))<10 THEN RAISE EXCEPTION 'outside_150m_or_unverified_reason_required'; END IF; END IF; END IF; RETURN NEW; END $$;